import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const resources = {
    materials: [],
    geometries: [],
    textures: [],
    timelines: [],
  };

  // Load primary gear from GLB
  const gltf = ctx.glbLoader.load(config.meshUrl);
  let primaryMesh = null;
  gltf.scene.traverse((child) => {
    if (!primaryMesh && child.isMesh) {
      primaryMesh = child;
    }
  });

  // Create primary gear group
  const primaryGear = new THREE.Group();
  if (primaryMesh) {
    const gearClone = primaryMesh.clone();
    const gearMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x555555,
      roughness: 0.5,
      metalness: 0.55,
      clearcoat: 0.2,
      clearcoatRoughness: 0.3,
      anisotropy: 0.7,
    });
    gearClone.material = gearMaterial;
    resources.materials.push(gearMaterial);
    primaryGear.add(gearClone);
  }
  root.add(primaryGear);

  // Create secondary gear (scaled instance)
  const secondaryGear = primaryGear.clone();
  secondaryGear.position.set(1.15, 0.35, -0.1);
  secondaryGear.scale.multiplyScalar(0.9 / 1.6);
  root.add(secondaryGear);

  // Create jewel pivot
  const jewelGeometry = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMaterial = new THREE.MeshPhysicalMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
  });
  const jewelPivot = new THREE.Mesh(jewelGeometry, jewelMaterial);
  root.add(jewelPivot);
  resources.geometries.push(jewelGeometry);
  resources.materials.push(jewelMaterial);

  // Create arbor shafts
  const arborGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const arborMaterial = new THREE.MeshStandardMaterial({
    color: 0x16161d,
    roughness: 0.8,
    metalness: 0.3,
  });

  const primaryArbor = new THREE.Mesh(arborGeometry, arborMaterial);
  root.add(primaryArbor);

  const secondaryArborMat = arborMaterial.clone();
  const secondaryArbor = new THREE.Mesh(arborGeometry.clone(), secondaryArborMat);
  secondaryArbor.position.set(1.15, 0.35, -0.1);
  root.add(secondaryArbor);

  resources.geometries.push(arborGeometry);
  resources.materials.push(arborMaterial, secondaryArborMat);

  // Create contact shadow
  const shadowGeometry = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMaterial = new THREE.ShadowMaterial({ opacity: 0.5 });
  const contactShadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  contactShadow.position.y = -1.2;
  contactShadow.position.z = -0.01;
  root.add(contactShadow);
  resources.geometries.push(shadowGeometry);
  resources.materials.push(shadowMaterial);

  // Create backdrop plane with gradient
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const gradientTexture = createGradientTexture(config.colors?.gradientStops);
  const backdropMaterial = new THREE.MeshBasicMaterial({ map: gradientTexture });
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -3;
  root.add(backdrop);
  resources.geometries.push(backdropGeometry);
  resources.materials.push(backdropMaterial);
  resources.textures.push(gradientTexture);

  // Setup fog
  root.fog = new THREE.Fog(0x0b0b10, 5, 11);

  // Add text via fontAtlas
  if (ctx.fontAtlas) {
    try {
      const headlineText = ctx.fontAtlas.createText('The going train', {
        fontSize: 0.34,
        fontFamily: 'Lora',
        fontWeight: 600,
      });
      if (headlineText) {
        headlineText.position.y = -1.7;
        root.add(headlineText);
      }
    } catch (e) {
      // Fallback silent fail
    }

    try {
      const captionText = ctx.fontAtlas.createText('34 COMPONENTS / HAND-FINISHED', {
        fontSize: 0.09,
        fontFamily: 'JetBrains Mono',
        fontWeight: 400,
        letterSpacing: 0.08,
      });
      if (captionText) {
        captionText.position.y = -2.1;
        root.add(captionText);
      }
    } catch (e) {
      // Fallback silent fail
    }
  }

  // Setup gear rotation animation
  const rotationTimeline = gsap.timeline({ repeat: -1 });
  rotationTimeline.to(primaryGear.rotation, {
    z: Math.PI * 2,
    duration: 2 * Math.PI / 0.08,
    ease: 'none',
  }, 0);
  rotationTimeline.to(secondaryGear.rotation, {
    z: -Math.PI * 2,
    duration: 2 * Math.PI / 0.142,
    ease: 'none',
  }, 0);
  resources.timelines.push(rotationTimeline);

  // Apply orbit primitive
  if (ctx.primitives?.orbit) {
    ctx.primitives.orbit(root, { speed: 0.08, radius: 0.2 });
  }

  // Cleanup
  root.userData.cleanup = () => {
    resources.timelines.forEach((tl) => tl.kill());
    resources.geometries.forEach((geo) => geo.dispose());
    resources.materials.forEach((mat) => mat.dispose());
    resources.textures.forEach((tex) => tex.dispose());
  };

  root.userData.handlers = {};

  return root;
}

function createGradientTexture(stops) {
  const width = 512;
  const height = 512;
  const data = new Uint8Array(width * height * 4);

  const defaultStops = [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const gradientStops = stops || defaultStops;

  const hexToRGB = (hex) => {
    const h = hex.replace('#', '');
    return [
      parseInt(h.substr(0, 2), 16),
      parseInt(h.substr(2, 2), 16),
      parseInt(h.substr(4, 2), 16),
    ];
  };

  for (let i = 0; i < height; i++) {
    const t = i / (height - 1);
    let r, g, b;

    let stop1 = gradientStops[0];
    let stop2 = gradientStops[gradientStops.length - 1];

    for (let j = 0; j < gradientStops.length - 1; j++) {
      if (t >= gradientStops[j].at && t <= gradientStops[j + 1].at) {
        stop1 = gradientStops[j];
        stop2 = gradientStops[j + 1];
        break;
      }
    }

    const localT =
      stop2.at === stop1.at ? 0 : (t - stop1.at) / (stop2.at - stop1.at);
    const rgb1 = hexToRGB(stop1.hex);
    const rgb2 = hexToRGB(stop2.hex);

    r = Math.round(rgb1[0] + (rgb2[0] - rgb1[0]) * localT);
    g = Math.round(rgb1[1] + (rgb2[1] - rgb1[1]) * localT);
    b = Math.round(rgb1[2] + (rgb2[2] - rgb1[2]) * localT);

    for (let j = 0; j < width; j++) {
      const index = (i * width + j) * 4;
      data[index] = r;
      data[index + 1] = g;
      data[index + 2] = b;
      data[index + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}
